{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-f3j5Ff/src/diff.js","content":"/**
 * Line-based diff of a side document against the base it derives from.
 *
 * Produces the list of changes: runs of base lines replaced by runs of the
 * side's lines, in the order they occur in the base. An insertion replaces
 * zero base lines and a deletion contributes zero side lines.
 */

/**
 * Computes the changes that turn `base` into `side`, using a longest common
 * subsequence over whole lines (compared as exact strings). Ties in the LCS
 * are broken by preferring matches that occur earliest: walking both
 * documents from the start, a match is taken whenever the current lines are
 * equal, and otherwise the side whose remaining subsequence is at least as
 * long as the other's is advanced, preferring to advance the base on a tie.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]}
 */
export function diffAgainstBase(base, side) {
  const n = base.length
  const m = side.length

  // suffixLcs[i][j] = length of the LCS of base[i:] and side[j:].
  const suffixLcs = new Array(n + 1)
  for (let i = 0; i <= n; i++) suffixLcs[i] = new Uint32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = suffixLcs[i]
    const nextRow = suffixLcs[i + 1]
    const baseLine = base[i]
    for (let j = m - 1; j >= 0; j--) {
      if (baseLine === side[j]) {
        row[j] = nextRow[j + 1] + 1
      } else {
        const skipBase = nextRow[j]
        const skipSide = row[j + 1]
        row[j] = skipBase >= skipSide ? skipBase : skipSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (suffixLcs[i + 1][j] >= suffixLcs[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevI = 0
  let prevJ = 0
  for (const [mi, mj] of matches) {
    if (mi > prevI || mj > prevJ) {
      changes.push({ baseStart: prevI, baseEnd: mi, sideStart: prevJ, sideEnd: mj })
    }
    prevI = mi + 1
    prevJ = mj + 1
  }
  if (prevI < n || prevJ < m) {
    changes.push({ baseStart: prevI, baseEnd: n, sideStart: prevJ, sideEnd: m })
  }

  return changes
}
"}

