{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-f3j5Ff/src/merge.js","content":"import { diffAgainstBase } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Groups the changes from both sides into merge regions.
 *
 * Changes are ordered by where they start in the base, with mine's changes
 * before theirs's when they start at the same place. Overlapping and
 * touching changes (a change starting at or before the current region's
 * end) are absorbed into the same region.
 *
 * @param {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]} mineChanges
 * @param {{baseStart: number, baseEnd: number, sideStart: number, sideEnd: number}[]} theirsChanges
 * @returns {{start: number, end: number, changes: object[]}[]}
 */
function buildRegions(mineChanges, theirsChanges) {
  const all = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' })),
  ]
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let idx = 0
  while (idx < all.length) {
    const first = all[idx]
    idx++
    let end = first.baseEnd
    const changes = [first]
    while (idx < all.length && all[idx].baseStart <= end) {
      changes.push(all[idx])
      if (all[idx].baseEnd > end) end = all[idx].baseEnd
      idx++
    }
    regions.push({ start: first.baseStart, end, changes })
  }
  return regions
}

/**
 * Computes a side's replacement lines for a region: the run from the
 * smallest start of that side's own changes in the region, moved back by
 * however far the region begins before those changes do in the base, to the
 * largest end of that side's own changes, moved forward by however far the
 * region ends after them. A side untouched in a region contributes the
 * base lines of the whole region, since it made no change there.
 */
function sideLinesForRegion(region, sideChanges, sideDoc, baseDoc) {
  if (sideChanges.length === 0) {
    return baseDoc.slice(region.start, region.end)
  }
  let first = sideChanges[0]
  let last = sideChanges[0]
  for (const c of sideChanges) {
    if (c.baseStart < first.baseStart) first = c
    if (c.baseEnd > last.baseEnd) last = c
  }
  const begin = first.sideStart - (first.baseStart - region.start)
  const end = last.sideEnd + (region.end - last.baseEnd)
  return sideDoc.slice(begin, end)
}

/**
 * Resolves a region to either a clean set of lines or a conflict, per the
 * cascade: equal sides resolve to mine, an unchanged mine resolves to
 * theirs, an unchanged theirs resolves to mine, and anything else conflicts.
 *
 * @returns {{conflict: false, kind: 'mine'|'theirs'|'both', lines: string[]}
 *         | {conflict: true, mineLines: string[], baseLines: string[], theirsLines: string[]}}
 */
function resolveRegion(region, mineDoc, baseDoc, theirsDoc) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mineLines = sideLinesForRegion(region, mineChanges, mineDoc, baseDoc)
  const theirsLines = sideLinesForRegion(region, theirsChanges, theirsDoc, baseDoc)
  const baseLines = baseDoc.slice(region.start, region.end)

  if (arraysEqual(mineLines, theirsLines)) {
    const mineTouched = mineChanges.length > 0
    const theirsTouched = theirsChanges.length > 0
    const kind = mineTouched && theirsTouched ? 'both' : mineTouched ? 'mine' : 'theirs'
    return { conflict: false, kind, lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { conflict: false, kind: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { conflict: false, kind: 'mine', lines: mineLines }
  }
  return { conflict: true, mineLines, baseLines, theirsLines }
}

/**
 * Computes the full merge plan: an ordered list of stable and resolved
 * regions spanning the whole base document.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Array<
 *   | {type: 'stable', lines: string[]}
 *   | {type: 'clean', kind: 'mine'|'theirs'|'both', lines: string[]}
 *   | {type: 'conflict', mineLines: string[], baseLines: string[], theirsLines: string[]}
 * >}
 */
export function planMerge(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine)
  const theirsChanges = diffAgainstBase(base, theirs)
  const regions = buildRegions(mineChanges, theirsChanges)

  const plan = []
  let prevEnd = 0
  for (const region of regions) {
    if (region.start > prevEnd) {
      plan.push({ type: 'stable', lines: base.slice(prevEnd, region.start) })
    }
    const resolved = resolveRegion(region, mine, base, theirs)
    if (resolved.conflict) {
      plan.push({
        type: 'conflict',
        mineLines: resolved.mineLines,
        baseLines: resolved.baseLines,
        theirsLines: resolved.theirsLines,
      })
    } else {
      plan.push({ type: 'clean', kind: resolved.kind, lines: resolved.lines })
    }
    prevEnd = region.end
  }
  if (prevEnd < base.length) {
    plan.push({ type: 'stable', lines: base.slice(prevEnd, base.length) })
  }

  return plan
}
"}

