import { spawnSync } from 'node:child_process'

function run(mode, mine, base, theirs) {
  const input = [mine, base, theirs].map(part => part.map(l => l + '\n').join('')).join('%%%\n')
  const r = spawnSync(process.execPath, ['src/cli.js', mode], { encoding: 'utf8', input })
  return r
}

let r = run('regions', ['a','X','b'], ['a','b'], ['a','X','b'])
console.log('both-check:', JSON.stringify(r.stdout), 'exit', r.status)

r = run('regions', ['a','X','c','Y','e'], ['a','b','c','d','e'], ['a','b','c','d','e'])
console.log('two-separate-mine-changes:', JSON.stringify(r.stdout), 'exit', r.status)

r = run('merge', ['a','P','b'], ['a','b'], ['a','Q','b'])
console.log('same-insert-point-conflict:', JSON.stringify(r.stdout), 'exit', r.status)

r = run('merge', [], [], [])
console.log('all-empty:', JSON.stringify(r.stdout), 'exit', r.status)

// document with a line literally '%%%' is impossible to represent (would be mistaken for separator) - skip

r = run('regions', ['a','b'], ['a','b'], ['a','b'])
console.log('all-clean:', JSON.stringify(r.stdout), 'exit', r.status)
EOF
